import React,{useState,useEffect,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {Aperture,Sparkles,Clapperboard,Images,Database,Users,Layers,Cpu,Activity,Settings,HelpCircle,ArrowUpRight,ArrowRight,Plus,Upload,Download,Play,Pause,X,Check,RefreshCw,Trash2,ChevronDown,LogOut,BookOpen,SlidersHorizontal,Camera,Cloud,Link,Clock,Zap,ShieldCheck,Copy,Search,Menu} from 'lucide-react';
import './style.css';
import {connectionCommand} from './compute.js';
const icons={studio:Aperture,characters:Users,datasets:Database,gallery:Images,models:Layers,resources:Cpu,jobs:Activity,help:HelpCircle,settings:Settings};
const nav=[['studio','Студия'],['characters','Персонажи'],['datasets','Датасеты'],['gallery','Галерея'],['models','Модели и LoRA'],['resources','Мощности'],['jobs','Задачи'],['help','Помощь'],['settings','Настройки']];
async function api(path,method='GET',body){const options={method,credentials:'same-origin',headers:{}};if(body instanceof FormData)options.body=body;else if(body!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}const r=await fetch('/api'+path,options);let data;try{data=await r.json()}catch{throw Error('Сервер недоступен')}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:data.detail?.message?data.detail.message+(data.detail.operation_id?' · операция '+data.detail.operation_id:''):JSON.stringify(data.detail));return data}
const time=s=>s==null?'Нет замера':s<60?`${Math.ceil(s)} сек`:`${Math.round(s/60)} мин`;
const statuses={queued:'В очереди',running:'Выполняется',cancelling:'Отменяется',cancelled:'Отменено',failed:'Ошибка',succeeded:'Готово',connection_lost:'Связь потеряна'};
function Button({children,icon:Icon,subtle=false,danger=false,...props}){return <button className={`${subtle?'secondary':'primary'} ${danger?'danger':''}`} {...props}>{Icon&&<Icon size={16}/>} {children}</button>}
function Field({label,hint,children}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function NumberField({label,value,onChange,hint,...props}){return <Field label={label} hint={hint}><input type="number" value={value??''} onChange={e=>onChange(Number(e.target.value))} {...props}/></Field>}
function Empty({icon:Icon=Images,title,children}){return <div className="empty"><div className="empty-icon"><Icon size={29}/></div><h3>{title}</h3><p>{children}</p></div>}
function Modal({title,children,onClose}){useEffect(()=>{const f=e=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',f);return()=>window.removeEventListener('keydown',f)},[]);return <div className="modal-backdrop" onClick={onClose}><section className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><div className="section-head"><h2>{title}</h2><button className="icon" aria-label="Закрыть" onClick={onClose}><X/></button></div>{children}</section></div>}
function App(){
 const [auth,setAuth]=useState(null),[password,setPassword]=useState(''),[page,setPage]=useState('studio'),[data,setData]=useState({recipes:[],characters:[],datasets:[],profiles:[],adapters:[],workers:[],jobs:[],artifacts:[],nodes:[],overview:{}}),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[modal,setModal]=useState(null),[draft,setDraft]=useState(null);
 const [rid,setRid]=useState('krea.generate'),[character,setCharacter]=useState('may'),[params,setParams]=useState({prompt:'MayMay_model, candid photograph in a sunlit apartment, natural expression, detailed surroundings, realistic skin texture'}),[assignment,setAssignment]=useState('');
 useEffect(()=>{api('/session').then(setAuth).catch(e=>setError(e.message))},[]);
 const refresh=useCallback(async()=>{const keys=['recipes','characters','datasets','profiles','adapters','workers','jobs','artifacts','overview'];const values=await Promise.all(keys.map(k=>api('/'+k)));const nodes=[];const weights=await api('/artifacts?kind=all');setData(Object.fromEntries([...keys.map((k,i)=>[k,values[i]]),['nodes',nodes],['weights',weights.filter(a=>['state','lora','weights'].includes(a.kind))]]))},[]);
 useEffect(()=>{if(!auth?.authenticated)return;refresh().catch(e=>setError(e.message));const id=setInterval(()=>refresh().catch(()=>{}),6000);return()=>clearInterval(id)},[auth?.authenticated]);
 useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(id)},[notice]);
 const act=async(fn,message)=>{setError('');setBusy(true);try{const result=await fn();if(message)setNotice(message);await refresh();return result}catch(e){setError(e.message);return null}finally{setBusy(false)}};
 const recipe=data.recipes.find(r=>r.id===rid);const chooseRecipe=id=>{const r=data.recipes.find(x=>x.id===id);setRid(id);setParams(p=>({...r?.defaults,prompt:p.prompt||'',negative_prompt:p.negative_prompt||'',dataset_id:p.dataset_id,reference_id:p.reference_id,adapters:[]}))};
 useEffect(()=>{if(recipe&&params.steps===undefined)setParams(p=>({...recipe.defaults,...p}))},[recipe]);
 const set=(k,v)=>setParams(p=>({...p,[k]:v}));
 const openStudio=(artifact,video=false)=>{const id=video?'wan.i2v.generate':artifact.meta?.recipe||'krea.generate';const r=data.recipes.find(x=>x.id===id&&x.kind==='generate');setRid(r?.id||'krea.generate');setParams({...r?.defaults,...artifact.meta?.params,reference_id:video?artifact.id:undefined,adapters:[],components:undefined});setPage('studio');setModal(null)};
 if(auth===null)return <div className="login"><Aperture className="spin"/><p>Открываем студию…</p>{error&&<p>{error}</p>}</div>;
 if(!auth.authenticated)return <div className="login"><div className="login-card glass"><div className="logo-mark"><Aperture size={32}/></div><p className="eyebrow">YOUR PERSONAL CREATIVE SPACE</p><h1>MayMay<span> Studio</span></h1><p>Фото. Движение. Ваши персонажи.</p><form onSubmit={e=>{e.preventDefault();api('/login','POST',{password}).then(()=>setAuth({...auth,authenticated:true})).catch(e=>setError(e.message))}}><Field label="Пароль студии"><input autoFocus type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></Field><Button icon={ArrowRight}>Открыть студию</Button></form>{auth.local&&<small>Локальный запуск: maymay-local</small>}{error&&<div className="alert error">{error}</div>}</div></div>;
 const common={data,act,busy,setModal,setPage,character,setCharacter,refresh};
 return <div className="app"><aside className="sidebar"><a className="brand" href="#" onClick={e=>{e.preventDefault();setPage('studio')}}><span className="logo-mark"><Aperture size={25}/></span><span>MayMay<small>STUDIO / 03</small></span></a><p className="nav-caption">CREATIVE WORKSPACE</p><nav>{nav.map(([id,label])=>{const I=icons[id];return <button key={id} className={page===id?'active':''} onClick={()=>{setPage(id);setError('')}}><I size={19}/><span>{label}</span>{id==='jobs'&&data.overview.active_jobs>0&&<b>{data.overview.active_jobs}</b>}</button>})}</nav><div className="sidebar-bottom"><div className="avatar">M</div><div>Личная студия<small>Ваше пространство</small></div><button className="icon" title="Выйти" onClick={()=>api('/logout','POST',{}).then(()=>setAuth({...auth,authenticated:false}))}><LogOut size={17}/></button></div></aside>
 <main><header className="topbar"><span className="breadcrumbs">Workspace <span>/</span> {nav.find(x=>x[0]===page)?.[1]}</span><div className="top-status"><span className={'dot '+(data.overview.workers?'':'offline')}/>{data.overview.workers?`${data.overview.workers} GPU-агент онлайн`:'GPU не подключена'}<button className="icon" aria-label="Обновить" onClick={()=>act(refresh)}><RefreshCw size={16}/></button></div></header><div className="content">{error&&<div role="alert" className="alert error">{error}<button className="icon" onClick={()=>setError('')} aria-label="Закрыть ошибку"><X size={16}/></button></div>}{notice&&<div role="status" className="toast"><Check size={16}/>{notice}</div>}
 {page==='studio'&&<><div className="page-title"><div><p className="eyebrow">MAKE SOMETHING THAT FEELS REAL</p><h1>Ваша следующая история<span>.</span></h1><p>От идеи до кадра. От кадра — к движению.</p></div><span className="version-label">MAYMAY / STUDIO 3</span></div><div className="studio-layout"><section className="panel composer"><div className="segmented"><button className={rid.includes('wan')?'':'selected'} onClick={()=>chooseRecipe('krea.generate')}><Camera size={16}/>Фото</button><button className={rid.includes('wan')?'selected':''} onClick={()=>chooseRecipe('wan.i2v.generate')}><Clapperboard size={16}/>Видео</button></div><div className="row two"><Field label="Персонаж"><select value={character} onChange={e=>setCharacter(e.target.value)}>{data.characters.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Пайплайн"><select value={rid} onChange={e=>chooseRecipe(e.target.value)}>{data.recipes.filter(r=>r.kind==='generate'&&(rid.includes('wan')?r.family.startsWith('wan'):!r.family.startsWith('wan'))).map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></Field></div><Field label="Как выглядит ваша сцена?" hint="Опишите действие, одежду, окружение и свет. Используйте триггер персонажа."><textarea className="prompt" value={params.prompt||''} onChange={e=>set('prompt',e.target.value)} placeholder="MayMay_model, …"/></Field>
 {recipe?.edit&&<Reference value={params.reference_id} onChange={v=>set('reference_id',v)} {...common}/>}
 <div className="row two"><Field label="Формат кадра"><select value={`${params.width||1024}x${params.height||1024}`} onChange={e=>{const[w,h]=e.target.value.split('x').map(Number);setParams(p=>({...p,width:w,height:h}))}}>{(rid==='wan.5b.generate'?[[1280,704],[704,1280]]:rid.includes('wan')?[[832,480],[480,832],[1280,720],[720,1280]]:[[1024,1024],[768,1024],[1024,768],[832,1216]]).map(([w,h])=><option key={w+'x'+h} value={w+'x'+h}>{w} × {h}</option>)}</select></Field><NumberField label="Вариантов" value={params.count||1} min={1} max={8} onChange={v=>set('count',v)}/></div>
 <ProfilePicker recipe={recipe} data={data} value={params.profile_id} onChange={v=>set('profile_id',v)}/><AdapterPicker family={recipe?.family} value={params.adapters||[]} onChange={v=>set('adapters',v)} {...common}/>
 <details className="advanced"><summary><SlidersHorizontal size={16}/>Расширенные настройки<ChevronDown size={15}/></summary><div className="row two"><NumberField label="Steps" value={params.steps} onChange={v=>set('steps',v)} hint="Больше шагов — дольше генерация. Turbo использует короткое расписание."/><NumberField label="Seed" value={params.seed} onChange={v=>set('seed',v)} hint="Сохраняйте seed для сравнения вариантов."/>{rid!=='krea.generate'&&<NumberField label="Guidance" value={params.guidance} step={.5} onChange={v=>set('guidance',v)}/>} {rid.includes('wan')&&<><NumberField label="Кадры" value={params.frames} step={4} onChange={v=>set('frames',v)} hint="Допустимое число — 4n+1."/><NumberField label="FPS экспорта" value={params.fps} onChange={v=>set('fps',v)}/></>}</div>{recipe?.negative?<Field label="Negative prompt"><textarea value={params.negative_prompt||''} onChange={e=>set('negative_prompt',e.target.value)}/></Field>:<div className="hint">Turbo работает без CFG: negative prompt здесь не применяется.</div>}<Memory params={params} set={set}/></details>
 <Assignment assignment={assignment} setAssignment={setAssignment} {...common}/><Button disabled={busy} icon={Sparkles} onClick={()=>act(async()=>{const j=await api('/jobs','POST',{recipe:rid,character_id:character,profile_id:params.profile_id||recipe.family,params,worker_id:assignment.startsWith('w:')?assignment.slice(2):null,node_id:assignment.startsWith('n:')?assignment.slice(2):null});setPage('jobs');return j},'Задание добавлено в очередь')}>Создать {rid.includes('wan')?'видео':'фотографию'}<ArrowUpRight size={17}/></Button><small className="subtext">Подготовка и вычисления выполняются на выбранном GPU. Закрытие страницы не отменяет задачу.</small></section>
 <div className="studio-right"><section className="character-hero">{data.characters.find(c=>c.id===character)?.face_url?<img src={data.characters.find(c=>c.id===character).face_url} alt="Эталон лица персонажа"/>:<div className="character-placeholder">{data.characters.find(c=>c.id===character)?.name?.slice(0,1)}</div>}<div className="hero-shade"/><div className="hero-top"><span className="pill">CHARACTER REFERENCE</span><span className="pill translucent">CHARACTER</span></div><div className="hero-bottom"><p>THE FACE BEHIND YOUR STORIES</p><h2>{data.characters.find(c=>c.id===character)?.name||'May'}<span> / character</span></h2><p>Эталон внешности · не результат новой генерации</p></div></section><section className="panel mini-panel"><span className="circle-icon"><Clapperboard size={20}/></span><div><h3>Дайте фотографии движение</h3><p>Выберите кадр из галереи и отправьте в Wan I2V.</p></div><button className="icon" onClick={()=>setPage('gallery')} aria-label="Открыть галерею"><ArrowUpRight/></button></section><div className="small-stats"><div><b>{data.overview.media||0}</b><span>кадров и видео</span></div><div><b>{data.overview.characters||1}</b><span>персонажей</span></div><div><b>{data.overview.active_jobs||0}</b><span>активных задач</span></div></div></div></div></>}
 {page==='characters'&&<Characters {...common}/>}
 {page==='datasets'&&<Datasets {...common}/>}
 {page==='gallery'&&<Gallery {...common} openStudio={openStudio}/>}
 {page==='models'&&<Models {...common}/>}
 {page==='resources'&&<Resources {...common} recipeId={rid} params={params} setAssignment={setAssignment}/>}
 {page==='jobs'&&<Jobs {...common} openResume={a=>{setModal(null);setPage('train');setDraft(a)}}/>}
 {page==='train'&&<Training {...common} draft={draft}/>}
 {page==='help'&&<Help/>}
 {page==='settings'&&<SettingsPage {...common}/>}
 </div><footer>MayMay Studio <span>PERSONAL CONTENT SYSTEM / V3</span><button onClick={()=>setPage('help')}>Руководство <ArrowUpRight size={12}/></button></footer></main>{modal&&<Modal title={modal.title} onClose={()=>setModal(null)}>{modal.body}</Modal>}</div>
}
function Title({eyebrow,title,description,children}){return <div className="page-title"><div><p className="eyebrow">{eyebrow}</p><h1>{title}<span>.</span></h1>{description&&<p>{description}</p>}</div>{children}</div>}
function Reference({value,onChange,data,act}){const [refs,setRefs]=useState([]);useEffect(()=>{api('/artifacts?kind=reference').then(setRefs)},[data.artifacts]);return <Field label="Исходное изображение / референс"><div className="reference-row"><select value={value||''} onChange={e=>onChange(e.target.value)}><option value="">Выберите изображение</option>{[...refs,...data.artifacts.filter(a=>a.kind!=='video')].map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><label className="file-button"><Upload size={17}/><input type="file" accept="image/*" onChange={e=>{const f=e.target.files[0];if(!f)return;act(async()=>{const fd=new FormData();fd.append('file',f);const a=await api('/uploads','POST',fd);setRefs(x=>[a,...x]);onChange(a.id)},'Референс загружен')}}/></label></div></Field>}
function AdapterPicker({family,value,onChange,data}){const candidates=data.adapters.filter(a=>a.family===family);return <div className="adapter-picker"><div className="section-head"><span className="label">LoRA</span><span className="muted">{value.length} подключено</span></div>{candidates.length===0?<p className="hint">Добавьте адаптер в разделе «Модели и LoRA» или обучите персонажа.</p>:<><select value="" onChange={e=>{if(e.target.value&&!value.some(x=>x.id===e.target.value))onChange([...value,{id:e.target.value,weight:1}])}}><option value="">+ Подключить совместимую LoRA</option>{candidates.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select>{value.map(a=><div key={a.id} className="lora-row"><span>{candidates.find(x=>x.id===a.id)?.name||a.id}</span><input aria-label="Вес LoRA" type="number" min={-2} max={2} step={.1} value={a.weight} onChange={e=>onChange(value.map(x=>x.id===a.id?{...x,weight:Number(e.target.value)}:x))}/><button className="icon" onClick={()=>onChange(value.filter(x=>x.id!==a.id))} aria-label="Отключить LoRA"><X size={15}/></button></div>)}</>}</div>}
function Assignment({assignment,setAssignment,data,setPage}){return <Field label="Вычислитель"><div className="reference-row"><select value={assignment} onChange={e=>setAssignment(e.target.value)}><option value="">Следующий свободный подключённый агент</option>{data.workers.map(w=><option key={w.id} value={'w:'+w.id}>{w.name} · {w.online?'онлайн':'офлайн'}</option>)}</select><button className="icon bordered" title="Подключить GPU-агента" onClick={()=>setPage('resources')}><Cpu size={18}/></button></div></Field>}
function Memory({params,set}){return <div className="memory-box"><label className="check"><input type="checkbox" checked={!!params.fp8} onChange={e=>set('fp8',e.target.checked)}/>Scaled FP8 для DiT <small>экономит память, требует проверки качества</small></label><NumberField label="Блоков в CPU" value={params.blocks_to_swap||0} onChange={v=>set('blocks_to_swap',v)} min={0} max={26} hint="Оставьте 0 при достаточной VRAM. Выгрузка в CPU может замедлять работу."/></div>}
function Characters({data,act,setPage,setModal}){return <><Title eyebrow="IDENTITY LIBRARY" title="Персонажи" description="Отдельные эталоны, триггеры и адаптеры для каждой личности."><Button icon={Plus} onClick={()=>setModal({title:'Новый персонаж',body:<CreateCharacter act={act} onDone={()=>setModal(null)}/>})}>Новый персонаж</Button></Title><div className="cards-grid">{data.characters.map(c=><section className="panel character-card" key={c.id}>{c.face_url?<img src={c.face_url} alt={c.name}/>:<div className="character-placeholder">{c.name.slice(0,1)}</div>}<div><h2>{c.name}</h2><code>{c.trigger}</code><p>{c.description}</p><div className="actions"><Button subtle icon={Layers} onClick={()=>setPage('train')}>Обучить LoRA</Button><Button subtle onClick={()=>setModal({title:'Эталоны '+c.name,body:<EditCharacter character={c} data={data} act={act} onDone={()=>setModal(null)}/>})}>Эталоны</Button></div></div></section>)}</div></>}
function CreateCharacter({act,onDone}){const [v,set]=useState({name:'',trigger:'',description:''});return <form onSubmit={e=>{e.preventDefault();act(async()=>{await api('/characters','POST',v);onDone()},'Персонаж создан')}}>{[['name','Имя'],['trigger','Уникальный английский триггер'],['description','Описание эталонов']].map(([k,l])=><Field key={k} label={l}><input required={k!=='description'} value={v[k]} onChange={e=>set({...v,[k]:e.target.value})}/></Field>)}<Button>Создать</Button></form>}
function Training({data,act,character,setCharacter,draft,setPage,...rest}){const [rid,setRid]=useState(draft?.meta?.recipe?.replace('.generate','.train')||'krea.train');const recipe=data.recipes.find(x=>x.id===rid)||data.recipes.find(x=>x.id==='krea.train');const [p,setP]=useState({...recipe?.defaults,...draft?.meta?.params,resume_artifact:draft?.id});const [assignment,setAssignment]=useState('');const set=(k,v)=>setP(x=>({...x,[k]:v}));return <><Title eyebrow="TEACH THE IDENTITY" title="Обучение персонажа" description="Версия датасета → LoRA → проверка на новых сценах."/><div className="split"><section className="panel"><Field label="Персонаж"><select value={character} onChange={e=>setCharacter(e.target.value)}>{data.characters.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Рецепт обучения"><select value={rid} onChange={e=>{setRid(e.target.value);setP(data.recipes.find(r=>r.id===e.target.value).defaults)}}>{data.recipes.filter(r=>r.kind==='train').map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></Field><ProfilePicker recipe={recipe} data={data} value={p.profile_id} onChange={v=>set('profile_id',v)}/><Field label="Датасет"><select value={p.dataset_id||''} onChange={e=>set('dataset_id',e.target.value)}><option value="">Выберите подготовленный набор</option>{data.datasets.filter(d=>d.character_id===character).map(d=><option key={d.id} value={d.id}>{d.name} · {d.count} примеров · v{d.revision}</option>)}</select></Field><div className="row two">{[['steps','Optimizer steps'],['rank','Rank / alpha'],['resolution','Разрешение'],['learning_rate','Learning rate'],['save_every','Сохранять каждые N шагов'],['preview_every','Preview каждые N шагов']].map(([k,l])=><NumberField key={k} label={l} value={p[k]} step={k==='learning_rate'?0.00001:1} onChange={v=>set(k,v)}/>)}</div>{rid.includes('wan')&&<Field label="Эксперт Wan"><select value={p.expert||'low'} onChange={e=>set('expert',e.target.value)}><option value="low">Low noise</option><option value="high">High noise</option><option value="both">Оба последовательно · больше времени</option></select></Field>}<Field label="Состояние для продолжения"><select value={p.resume_artifact||''} onChange={e=>set('resume_artifact',e.target.value)}><option value="">Начать новое обучение</option>{data.weights?.filter(a=>a.kind==='state').map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></Field><details className="advanced"><summary>Параметры памяти и batch</summary><div className="row two"><NumberField label="Batch size" value={p.batch_size||1} onChange={v=>set('batch_size',v)}/><NumberField label="Накопление градиента" value={p.gradient_accumulation||1} onChange={v=>set('gradient_accumulation',v)}/><NumberField label="Кадров в клипе Wan" value={p.frames||17} step={4} onChange={v=>set('frames',v)}/></div><Memory params={p} set={set}/></details><Assignment {...rest} data={data} assignment={assignment} setAssignment={setAssignment} setPage={setPage}/><Button icon={Play} onClick={()=>act(async()=>{await api('/jobs','POST',{recipe:rid,character_id:character,profile_id:p.profile_id||recipe.family,params:p,worker_id:assignment.startsWith('w:')?assignment.slice(2):null,node_id:assignment.startsWith('n:')?assignment.slice(2):null});setPage('jobs')},'Обучение добавлено в очередь')}>Начать обучение</Button></section><section className="panel guide"><div className="circle-icon"><ShieldCheck/></div><h2>Сначала качество.<br/>Затем больше шагов.</h2><p>Исходные параметры взяты из документации тренеров. Оптимальное число шагов для вашего персонажа выбирается по тестовым кадрам.</p><ol><li>Проверьте captions и уникальный триггер.</li><li>В «Модели и LoRA» проверьте доступ к компонентам.</li><li>Выберите или арендуйте GPU.</li><li>Сравнивайте preview с эталоном лица и фигуры.</li><li>Сохраните полное состояние для resume.</li></ol><div className="hint">Krea обучается на RAW. Встроенный preview выполняется на RAW с CFG. Turbo проверяется отдельной генерацией после сохранения LoRA.</div><div className="hint">Одна GPU на задачу. Multi-GPU обучение в этой сборке не включено: оно требует отдельной проверки тренера.</div></section></div></>}
function Datasets({data,act,character,setPage,setModal}){const [selected,setSelected]=useState(''),[items,setItems]=useState([]),[uploading,setUploading]=useState(false);const dataset=data.datasets.find(d=>d.id===selected);const load=()=>selected&&api(`/datasets/${selected}/items`).then(setItems);useEffect(()=>{load()},[selected,data.datasets]);const prepare=recipe=>act(()=>api('/jobs','POST',{recipe,character_id:dataset.character_id,params:{dataset_id:selected}}),'Подготовка добавлена в очередь');return <><Title eyebrow="PREPARE / CURATE / VERSION" title="Датасеты" description="Отберите материал. Исправьте описания. Зафиксируйте версию."><Button icon={Plus} onClick={()=>setModal({title:'Новый датасет',body:<CreateDataset data={data} act={act} character={character} onDone={d=>{setSelected(d.id);setModal(null)}}/>})}>Новый набор</Button></Title><div className="dataset-toolbar panel"><Field label="Рабочий набор"><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Выберите датасет</option>{data.datasets.map(d=><option key={d.id} value={d.id}>{d.name} · {d.count} файлов · v{d.revision}</option>)}</select></Field>{dataset&&<div className="actions"><label className="file-button wide"><Upload size={16}/>{uploading?'Загрузка…':'Добавить фото / ZIP / видео'}<input type="file" multiple disabled={uploading} accept="image/*,video/*,.zip" onChange={async e=>{setUploading(true);await act(async()=>{for(const file of e.target.files){const fd=new FormData();fd.append('file',file);await api(`/datasets/${selected}/upload`,'POST',fd)}await load()},'Материалы импортированы; точные дубликаты пропущены');setUploading(false)}}/></label><Button subtle icon={Sparkles} onClick={()=>prepare('dataset.caption')}>Описать материалы</Button><Button subtle icon={Clapperboard} onClick={()=>setModal({title:'Подготовка видео',body:<VideoSettings act={act} dataset={dataset} onDone={()=>setModal(null)}/>})}>Нарезать видео</Button><Button subtle icon={Download} onClick={()=>act(async()=>{const r=await api(`/datasets/${selected}/snapshot`,'POST',{});setModal({title:'Версия датасета готова',body:<><p>Train: {r.train} · Validation: {r.validation}</p><code className="break">{r.sha256}</code><p><a className="button primary" href={r.url}>Скачать ZIP с captions и manifest</a></p></>})})}>Экспорт версии</Button><Button subtle onClick={()=>setModal({title:'Настройки набора',body:<DatasetSettings dataset={dataset} act={act} onDone={()=>setModal(null)}/>})}>Настройки</Button><Button subtle onClick={()=>act(async()=>{const versions=await api(`/datasets/${selected}/versions`);setModal({title:'Сохранённые версии',body:<>{versions.map(v=><p key={v.sha256}><a href={v.url}>v{v.revision} · {v.sha256.slice(0,12)} · ZIP</a></p>)}</>})})}>История версий</Button><Button subtle danger onClick={()=>setModal({title:'Удалить датасет?',body:<><p>Редактируемый набор будет удалён. Исторические snapshot и объекты хранилища сохранятся.</p><Button danger onClick={()=>act(async()=>{await api(`/datasets/${selected}?confirm=true`,'DELETE');setSelected('');setItems([]);setModal(null)})}>Удалить набор</Button></>})}>Удалить набор</Button><Button icon={Layers} onClick={()=>setPage('train')}>Обучить</Button></div>}</div>{!dataset?<Empty icon={Database} title="Выберите или создайте набор">Фотографии и клипы сохраняются с captions, группами исходников и историей версий.</Empty>:items.length===0?<Empty icon={Upload} title="Добавьте исходные материалы">ZIP может содержать папки train и captions с совпадающими именами файлов.</Empty>:<><p className="hint">{items.filter(i=>i.accepted).length} принято · {items.length-items.filter(i=>i.accepted).length} исключено. Captioner и нарезка выполняются на агенте. Автоматические результаты требуют проверки.</p><div className="dataset-grid">{items.map(item=><DatasetItem key={item.id} item={item} act={act} reload={load} setModal={setModal}/>)}</div></>}</>}
function DatasetItem({item,act,reload,setModal}){const [caption,setCaption]=useState(item.caption),[group,setGroup]=useState(item.group_id);useEffect(()=>{setCaption(item.caption);setGroup(item.group_id)},[item.caption,item.group_id]);return <section className={'panel dataset-item '+(!item.accepted?'excluded':'')}>{item.kind==='video'?<video src={item.url} controls preload="metadata"/>:<img src={item.url} loading="lazy" alt={item.name}/>}<div className="item-body"><div className="section-head"><strong title={item.name}>{item.name}</strong><label className="check"><input type="checkbox" checked={item.accepted} onChange={e=>act(async()=>{await api('/items/'+item.id,'PATCH',{accepted:e.target.checked});reload()})}/>Принят</label></div>{item.quality.small&&<small className="warning-text">Исходник меньше 512 px</small>}<Field label="Caption"><textarea value={caption} onChange={e=>setCaption(e.target.value)}/></Field><Field label="Группа исходников" hint="Клипы одного видео должны оставаться в одной группе."><input value={group} onChange={e=>setGroup(e.target.value)}/></Field><Button subtle disabled={caption===item.caption&&group===item.group_id} onClick={()=>act(async()=>{await api('/items/'+item.id,'PATCH',{caption,group_id:group});reload()},'Описание сохранено')}>Сохранить</Button><Button subtle danger onClick={()=>setModal({title:'Удалить файл из набора?',body:<><p>Файл исчезнет из редактора. Сохранённые версии и общие объекты останутся доступны.</p><Button danger onClick={()=>act(async()=>{await api('/items/'+item.id+'?confirm=true','DELETE');setModal(null);reload()})}>Удалить</Button></>})}>Удалить файл</Button></div></section>}
function CreateDataset({data,act,character,onDone}){const [name,setName]=useState(''),[cid,setCid]=useState(character);return <form onSubmit={e=>{e.preventDefault();act(async()=>onDone(await api('/datasets','POST',{name,character_id:cid})))}}><Field label="Название"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Персонаж"><select value={cid} onChange={e=>setCid(e.target.value)}>{data.characters.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Button>Создать набор</Button></form>}
function Gallery({data,act,setModal,openStudio}){const [filter,setFilter]=useState('all'),[compare,setCompare]=useState([]),[search,setSearch]=useState('');const list=data.artifacts.filter(a=>(filter==='all'||(filter==='video'?a.kind==='video':a.kind!=='video'))&&JSON.stringify(a.meta).toLowerCase().includes(search.toLowerCase()));return <><Title eyebrow="YOUR CREATIVE ARCHIVE" title="Галерея" description="Фотографии и видео. Веса и служебные файлы находятся в разделе моделей."/><div className="gallery-toolbar"><div className="segmented small">{[['all','Все'],['image','Фото'],['video','Видео']].map(([id,label])=><button key={id} className={filter===id?'selected':''} onClick={()=>setFilter(id)}>{label}</button>)}</div><input className="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Поиск по сцене или модели"/>{compare.length===2&&<Button subtle onClick={()=>setModal({title:'Сравнение кадров',body:<div className="compare-grid">{compare.map(a=><div key={a.id}><img src={a.url} alt={a.name}/><p>{a.meta.recipe}</p></div>)}</div>})}>Сравнить 2 кадра</Button>}</div>{list.length===0?<Empty title="Здесь появятся ваши истории">Создайте первое фото или видео в студии. Служебные файлы никогда не попадут в эту ленту.</Empty>:<div className="gallery-grid">{list.map(a=><article className="gallery-item" key={a.id}><button className="media-open" onClick={()=>setModal({title:'Кадр и параметры',body:<ArtifactView artifact={a} act={act} openStudio={openStudio} data={data}/>})}>{a.kind==='video'?<><video src={a.url} preload="metadata"/><Clapperboard className="video-badge"/></>:<img src={a.url} alt={a.meta.params?.prompt||a.name} loading="lazy"/>}</button><div className="gallery-caption"><div><b>{a.meta.recipe}</b><small>{new Date(a.created*1000).toLocaleDateString('ru')}</small></div>{a.kind!=='video'&&<input aria-label="Выбрать для сравнения" type="checkbox" checked={compare.some(x=>x.id===a.id)} onChange={e=>setCompare(e.target.checked?[...compare.slice(-1),a]:compare.filter(x=>x.id!==a.id))}/>}<a className="icon" href={a.download_url} title="Скачать"><Download size={17}/></a></div></article>)}</div>}</>}
function ArtifactView({artifact:a,openStudio,act,data}){const [dataset,setDataset]=useState('');return <div className="artifact-view">{a.kind==='video'?<video src={a.url} controls autoPlay/>:<img src={a.url} alt={a.name}/>}<div><p className="eyebrow">{a.meta.recipe}</p><p>{a.meta.params?.prompt}</p><div className="actions"><a className="button primary" href={a.download_url}><Download size={16}/>Скачать</a><Button subtle onClick={()=>openStudio(a)}>Повторить настройки</Button>{a.kind!=='video'&&<Button subtle icon={Clapperboard} onClick={()=>openStudio(a,true)}>Оживить в Wan</Button>}<Button danger subtle icon={Trash2} onClick={()=>act(()=>api('/artifacts/'+a.id,'DELETE'),'Кадр убран из галереи')}>Убрать</Button></div><details><summary>Параметры</summary><pre>{JSON.stringify(a.meta.params,null,2)}</pre></details><Field label="Добавить в датасет через ручной отбор"><select value={dataset} onChange={e=>setDataset(e.target.value)}><option value="">Выберите набор</option>{data.datasets.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></Field><Button subtle disabled={!dataset} onClick={()=>act(()=>api(`/datasets/${dataset}/from-artifact`,'POST',{artifact_id:a.id}),'Добавлено как непринятый пример — проверьте caption')}>Добавить на проверку</Button></div></div>}
function Models({data,act,setModal,setPage}){const [selected,setSelected]=useState('krea2'),[json,setJson]=useState(''),[name,setName]=useState(''),[report,setReport]=useState(null),[weights,setWeights]=useState([]);const profile=data.profiles.find(p=>p.id===selected);useEffect(()=>{setJson(JSON.stringify(profile?.components||{},null,2));setName(profile?.name||'');setReport(null)},[selected,JSON.stringify(profile?.components)]);useEffect(()=>{api('/artifacts?kind=all').then(a=>setWeights(a.filter(x=>['lora','state','weights'].includes(x.kind))))},[data.jobs]);return <><Title eyebrow="ENGINES / ADAPTERS / RECIPES" title="Модели и LoRA" description="Готовые профили, свои компоненты и совместимые адаптеры."><Button icon={Layers} onClick={()=>setPage('train')}>Обучить LoRA</Button></Title><div className="split"><section className="panel"><Field label="Профиль"><select value={selected} onChange={e=>setSelected(e.target.value)}>{data.profiles.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Название"><input value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Компоненты" hint='HF: {"repo":"…","filename":"…","revision":"…"}; собственный файл на GPU: {"path":"/workspace/…"}.'><textarea className="code-editor" value={json} spellCheck={false} onChange={e=>setJson(e.target.value)}/></Field><div className="actions"><Button onClick={()=>act(()=>api('/profiles/'+selected,'PUT',{name,family:profile.family,components:JSON.parse(json)}),'Профиль сохранён')}>Сохранить</Button><Button subtle onClick={()=>act(async()=>{const id=profile.family+'-'+crypto.randomUUID().slice(0,8);await api('/profiles/'+id,'PUT',{name:name+' · копия',family:profile.family,components:JSON.parse(json)});setSelected(id)},'Создан собственный профиль')}>Сохранить копию</Button><Button subtle icon={ShieldCheck} onClick={()=>act(async()=>{const r=await api('/profiles/'+selected+'/check','POST',{});setReport(r);if(!r.ok)throw Error(r.errors.join('\n'));return r},'Доступ проверен, ревизии весов закреплены')}>Проверить доступ</Button><Button subtle danger disabled={['krea2','klein9','wan22-i2v','wan22-t2v','wan22-5b'].includes(selected)} onClick={()=>setModal({title:'Удалить пользовательский профиль?',body:<Button danger onClick={()=>act(async()=>{await api('/profiles/'+selected+'?confirm=true','DELETE');setSelected('krea2');setModal(null)})}>Подтвердить удаление</Button>})}>Удалить профиль</Button><Button subtle icon={RefreshCw} onClick={()=>act(()=>api('/profiles/'+selected+'/reset','POST',{}),'Preset восстановлен')}>Сбросить</Button></div>{report&&<div className={'alert '+(report.ok?'success':'error')}><div>{report.ok?'Компоненты доступны':'Требуется исправление'} · {(report.estimated_bytes/1e9).toFixed(1)} GB<br/>{Object.entries(report.components).map(([k,v])=><small key={k}>{k}: {v.status} · {v.license||'local'}<br/></small>)}</div></div>}<p className="hint">Проверка закрепляет точные ревизии. Она не подтверждает достаточность VRAM и не скачивает веса на веб-сервер.</p></section><section className="panel"><div className="section-head"><h2>Адаптеры</h2><Button subtle icon={Plus} onClick={()=>setModal({title:'Добавить LoRA',body:<AddAdapter data={data} act={act} onDone={()=>setModal(null)}/>})}>Добавить</Button></div>{data.adapters.length===0?<Empty icon={Layers} title="Подключите первую LoRA">Файл, ссылка Hugging Face/Civitai или результат обучения.</Empty>:data.adapters.map(a=><div className="list-row" key={a.id}><span className="circle-icon small"><Layers size={17}/></span><div><b>{a.name}</b><small>{a.family} · {a.expert} · {a.trigger}</small></div><button className="icon" onClick={()=>act(()=>api('/adapters/'+a.id,'DELETE'))} aria-label="Удалить LoRA"><Trash2 size={16}/></button></div>)}<h3>Веса и состояния обучения</h3>{weights.length===0?<p className="muted">Пока нет сохранённых весов.</p>:weights.map(a=><div className="list-row" key={a.id}><div><b>{a.name}</b><small>{a.kind} · {(a.size/1e6).toFixed(1)} MB</small></div><a className="icon" href={a.download_url} title="Скачать"><Download size={17}/></a></div>)}</section></div></>}
function AddAdapter({data,act,onDone}){const [v,set]=useState({name:'',source:'',family:'krea2',trigger:'',expert:'both'});const change=(k,val)=>set(x=>({...x,[k]:val}));return <form onSubmit={e=>{e.preventDefault();act(async()=>{await api('/adapters','POST',v);onDone()},'LoRA добавлена')}}><Field label="Название"><input required value={v.name} onChange={e=>change('name',e.target.value)}/></Field><Field label="Архитектура"><select value={v.family} onChange={e=>change('family',e.target.value)}>{['krea2','klein9','wan22-i2v','wan22-t2v'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Источник: прямая ссылка или путь на GPU"><input value={v.source} onChange={e=>change('source',e.target.value)} placeholder="https://huggingface.co/…/resolve/…"/></Field><label className="file-button wide"><Upload size={16}/>Загрузить .safetensors<input type="file" accept=".safetensors" onChange={e=>{const f=e.target.files[0];if(!f)return;act(async()=>{const fd=new FormData();fd.append('file',f);const a=await api('/uploads','POST',fd);change('source','artifact:'+a.id);change('name',f.name)},'Файл загружен')}}/></label><Field label="Trigger words"><input value={v.trigger} onChange={e=>change('trigger',e.target.value)}/></Field>{v.family.startsWith('wan')&&<Field label="Эксперт"><select value={v.expert} onChange={e=>change('expert',e.target.value)}><option value="both">Оба — только если адаптер совместим</option><option value="low">Low noise</option><option value="high">High noise</option></select></Field>}<p className="hint">При загрузке проверяется контейнер safetensors. Соответствие архитектуре проверяется при применении к модели; неверные адаптеры приводят к ошибке, а не к успешной пустой генерации.</p><Button disabled={!v.source}>Добавить адаптер</Button></form>}
const computeGuide=[
 ['Krea 2 · Turbo, фото','48 GB','64–96 GB','150 GB','1024 px, count 1. На 24 GB — только с FP8/block swap, медленнее.'],
 ['Krea 2 · LoRA RAW','48–80 GB','96–128 GB','200 GB','Batch 1, rank 16/32. На 24 GB возможен offload; сначала короткий тест.'],
 ['Klein Base 9B · фото / i2i','48 GB','64–96 GB','150 GB','Base: 50 шагов, CFG 4. На 24 GB потребуется экономия памяти.'],
 ['Klein Base 9B · LoRA','48–80 GB','96–128 GB','200 GB','Batch 1, checkpointing. Encoder Qwen3 8B: все 4 shards.'],
 ['Wan 2.2 A14B · I2V / T2V','80 GB','128 GB','250 GB','Начните с 832×480, 81 кадр. На 48 GB — FP8/block swap и отдельная проверка.'],
 ['Wan 2.2 A14B · LoRA I2V / T2V','80 GB','128 GB','300 GB','512 px, 17 кадров, batch 1; low/high последовательно. На 48 GB — offload.'],
 ['Wan 2.2 TI2V 5B · генерация','48 GB','64 GB','150 GB','24 GB — пробовать с CPU offload; 1280×704, 121 кадр. 5B LoRA не включена.'],
 ['Captions Qwen2.5-VL 3B','16–24 GB','32–64 GB','60 GB','BF16, сначала один пример. Видео описывается по 8 кадрам.'],
 ['Нарезка FFmpeg','GPU не нужна','16 GB','По объёму видео','CPU-агент может выполнять dataset.video.']
];
function Resources({data,act,setModal,setAssignment,setPage}){
 const [balance,setBalance]=useState(null),[balanceError,setBalanceError]=useState(''),[loading,setLoading]=useState(false);
 const updateBalance=async()=>{setLoading(true);try{setBalance(await api('/resources/balance'));setBalanceError('')}catch(e){setBalanceError(e.message);setBalance(null)}finally{setLoading(false)}};
 return <><Title eyebrow="CONNECT YOUR COMPUTE" title="Мощности" description="Создайте инстанс в YouGPU и подключите его к Studio. Арендой управляете вы."/>
 <div className="panel resource-summary"><div><Cloud size={24}/><div><b>Баланс YouGPU: {balance?balance.available.toFixed(2)+' ₽':'не загружен'}</b><p>{balance?'Общий расход '+balance.hourly_rate.toFixed(2)+' ₽/ч · накоплено '+balance.pending.toFixed(2)+' ₽':'Токен YouGPU нужен только для проверки баланса.'}</p>{balanceError&&<p role="alert">{balanceError}</p>}</div></div><Button subtle disabled={loading} onClick={updateBalance}>{loading?'Проверяем…':'Проверить баланс'}</Button></div>
 <section className="panel spaced"><h2>Подключить инстанс</h2><ol><li>Соберите GPU-образ через GitHub Actions → Build GPU agent и сделайте его публичным в GHCR.</li><li>Выберите ресурсы по таблице ниже. Создайте инстанс вручную в YouGPU с Docker и NVIDIA GPU, укажите свой SSH-ключ.</li><li>Получите код подключения. Он действует 15 минут и используется один раз.</li><li>Передайте адрес Studio и код контейнеру агента. Для первого запуска используйте инструкцию ниже.</li><li>Дождитесь агента онлайн и выберите его в студии или обучении.</li></ol>
 <Button icon={Link} onClick={()=>act(async()=>{const pair=await api('/workers/pair','POST',{});setModal({title:'Подключение GPU-агента',body:<ManualConnection pair={pair}/>})})}>Получить код и инструкцию</Button>
 <p className="hint">Отмена задачи и остановка контейнера не завершают аренду. После сохранения результатов завершите инстанс в YouGPU. Studio не создаёт, не останавливает и не удаляет инстансы в ручном режиме, в том числе по старым политикам простоя.</p></section>
 <h2 className="spaced">Агенты</h2>{!data.workers.length?<Empty icon={Cpu} title="Подключите первый агент">Аренда в YouGPU сама по себе не подключает агента. Нужен запущенный контейнер MayMay.</Empty>:data.workers.map(w=><section className="panel spaced" key={w.id}><h3>{w.name}</h3><p>{w.online?'Онлайн':'Нет связи'} · {w.capabilities.gpu} · {w.capabilities.gpu_count||0} GPU · {Math.round((w.capabilities.vram_mb_each||0)/1024)} GB VRAM на карту</p><p>Последний heartbeat: {w.heartbeat?new Date(w.heartbeat*1000).toLocaleString('ru'):'нет'}. {w.draining?'Новые задачи отключены':'Принимает задачи'}.</p>
 {data.jobs.filter(j=>j.worker_id===w.id&&!['succeeded','failed','cancelled'].includes(j.status)).map(j=><div key={j.id}><p>{j.stage} · {Math.round(j.progress*100)}% · {time(j.eta)}</p><progress max="1" value={j.progress}/></div>)}
 <div className="actions"><Button disabled={!w.online||w.draining} onClick={()=>{setAssignment('w:'+w.id);setPage('studio')}}>Выбрать для генерации</Button><Button subtle onClick={()=>act(()=>api('/workers/'+w.id,'PATCH',{draining:!w.draining}))}>{w.draining?'Принимать задачи':'Не брать новые'}</Button></div></section>)}
 <ComputeRecommendations/>
 </>
}
function ManualConnection({pair}){
 const [copied,setCopied]=useState(false),[copyError,setCopyError]=useState('');
 const command=connectionCommand(pair);
 return <><p>Одноразовый код действует 15 минут. Не публикуйте его в репозитории.</p><Field label="STUDIO_URL"><input readOnly value={pair.studio_url}/></Field><Field label="PAIRING_CODE"><textarea readOnly value={pair.pairing_code}/></Field>
 {pair.agent_image?<><Field label="Docker image"><textarea readOnly value={pair.agent_image}/></Field><p>При создании инстанса с поддержкой своего Docker-образа укажите этот image, переменные STUDIO_URL, PAIRING_CODE, WORKER_NAME=MayMay-GPU. Команда запуска — стандартная из образа. Смонтируйте постоянный рабочий диск в /workspace.</p><details open><summary>Инстанс уже создан: запуск через SSH / Termius</summary><p>На хосте нужны Docker, NVIDIA driver и NVIDIA Container Toolkit. Вставьте в терминал инстанса:</p><pre className="log">{command}</pre><Button subtle onClick={async()=>{try{await navigator.clipboard.writeText(command);setCopied(true);setCopyError('')}catch{setCopyError('Выделите и скопируйте команду вручную')}}}>{copied?'Скопировано':'Скопировать команду'}</Button>{copyError&&<p>{copyError}</p>}<p>Журнал: <code>docker logs --tail 100 -f maymay-agent</code>. Сохранённые credentials позволяют повторно запустить тот же контейнер без нового кода. Не запускайте второй агент поверх первого.</p></details></>:<p role="alert" className="alert">В настройках Timeweb задайте AGENT_IMAGE — публичный образ из Build GPU agent с тегом commit, затем выполните redeploy. Без образа готового GPU-окружения эта инструкция неполна.</p>}
 <p>Если агент уже установлен в готовом Python-окружении: задайте STUDIO_URL и PAIRING_CODE, затем выполните <code>python -m agent.main</code>. Не устанавливайте случайные версии Torch поверх окружения.</p>
 <p>Если код истёк — получите новый. Если регистрация могла пройти, но ответ потерян, проверьте список агентов и журнал контейнера. Не создавайте новую платную аренду для исправления регистрации.</p></>
}
function ComputeRecommendations(){return <section className="panel spaced"><h2>Какие ресурсы выбрать</h2><p>Ориентиры с запасом для первого запуска, а не измеренные минимумы. VRAM указана для одной карты, диск — свободное место под веса, кэш и результаты, без размера Docker-образа и исходного датасета.</p><div className="compute-table"><table><thead><tr>{['Пайплайн','VRAM','RAM','Свободный SSD','Начальные условия'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{computeGuide.map(row=><tr key={row[0]}>{row.map((v,i)=><td key={i}>{v}</td>)}</tr>)}</tbody></table></div><p>Для фото ориентир — RTX A6000 / RTX 6000 Ada 48 GB. Для тяжёлого Wan — A100 80 GB / H100 80 GB. RTX 4090 24 GB требует offload для тяжёлых задач. Больше VRAM не гарантирует скорость; цены проверяйте в YouGPU.</p><p>Одна задача использует одну GPU. Две карты по 24 GB не заменяют карту 48 GB. T4, P100, V100 не выбирайте для текущих BF16-пайплайнов. Для Krea/Klein начните с одной картинки, для Wan — с короткого клипа.</p><p>FP8 и block swap экономят VRAM за счёт качества/скорости и RAM. Сначала проверьте модель без LoRA, затем добавляйте адаптер. Время и стоимость без замера не обещаем.</p><details><summary>Источники и ограничения</summary><p>Рекомендации Studio — инженерный запас, реальная GPU-приёмка ещё не выполнена. Текущая версия фиксирует Musubi commit, а документация upstream развивается.</p><ul><li><a href="https://github.com/kohya-ss/musubi-tuner/blob/main/docs/krea2.md" target="_blank" rel="noreferrer">Krea 2 / Musubi</a></li><li><a href="https://github.com/kohya-ss/musubi-tuner/blob/main/docs/flux_2.md" target="_blank" rel="noreferrer">FLUX.2 / Musubi</a></li><li><a href="https://github.com/kohya-ss/musubi-tuner/blob/main/docs/wan.md" target="_blank" rel="noreferrer">Wan / Musubi</a></li><li><a href="https://github.com/Wan-Video/Wan2.2" target="_blank" rel="noreferrer">Официальный Wan 2.2</a></li></ul></details></section>}
function Jobs({data,act,setModal,setPage}){const [filter,setFilter]=useState('all');const jobs=data.jobs.filter(j=>filter==='all'||!['succeeded','failed','cancelled'].includes(j.status));return <><Title eyebrow="EVERY STEP, IN VIEW" title="Задачи" description="Подготовка, вычисления и сохранение — с отдельным прогрессом."><Button subtle icon={Layers} onClick={()=>setPage('train')}>Новое обучение</Button></Title><div className="segmented small"><button className={filter==='all'?'selected':''} onClick={()=>setFilter('all')}>Все</button><button className={filter==='active'?'selected':''} onClick={()=>setFilter('active')}>Активные</button></div>{!jobs.length?<Empty icon={Activity} title="Очередь свободна">Новые задачи появятся здесь. Ожидание GPU не расходует аренду само по себе.</Empty>:jobs.map(j=><section className="panel job" key={j.id}><div className="section-head"><div><small className="eyebrow">{j.id.slice(0,8)}</small><h3>{data.recipes.find(r=>r.id===j.recipe)?.name||j.recipe}</h3></div><span className={'status '+j.status}>{statuses[j.status]||j.status}</span></div><p>{j.stage}</p><progress max="1" value={j.progress} aria-label="Прогресс задачи"/><div className="job-details"><span>{Math.round(j.progress*100)}% · {j.eta!=null?'Осталось ≈ '+time(j.eta):'ETA появится после первых шагов'}</span>{j.metrics.seconds_per_step&&<span>{j.metrics.seconds_per_step.toFixed(2)} сек/шаг</span>}{j.metrics.loss!=null&&<span>Loss {j.metrics.loss.toFixed(4)}</span>}</div>{j.error&&<div className="alert error">{j.error}</div>}<div className="actions"><Button subtle onClick={()=>act(async()=>{const logs=await api('/jobs/'+j.id+'/logs');setModal({title:'Лог задачи',body:<pre className="log">{logs.map(l=>l.text).join('\n')||'Лог появится после подключения агента.'}</pre>})})}>Открыть лог</Button>{!['succeeded','failed','cancelled'].includes(j.status)&&<Button subtle danger onClick={()=>act(()=>api('/jobs/'+j.id+'/cancel','POST',{}),'Запрошена отмена')}>Отменить</Button>}{j.status==='connection_lost'&&<Button subtle onClick={()=>setModal({title:'Сверить потерянную задачу',body:<><p>Сначала проверьте в консоли YouGPU, что процессы задачи остановлены. Не запускайте повтор поверх работающей тренировки. После подтверждения задача будет закрыта, а агент отключён от новых работ.</p><Button danger onClick={()=>act(async()=>{await api('/jobs/'+j.id+'/reconcile','POST',{processes_stopped:true});setModal(null)},'Задача закрыта после вашей проверки')}>Процессы остановлены — закрыть задачу</Button></>})}>Сверить состояние</Button>}{['succeeded','failed','cancelled'].includes(j.status)&&<Button subtle icon={RefreshCw} onClick={()=>act(()=>api('/jobs/'+j.id+'/retry','POST',{}),'Создана новая попытка')}>Повторить</Button>}{['queued','succeeded','failed','cancelled'].includes(j.status)&&<button className="icon" aria-label="Удалить из очереди или истории" onClick={()=>act(()=>api('/jobs/'+j.id,'DELETE'),'Задание удалено')}><Trash2 size={17}/></button>}</div></section>)}</>}
function SettingsPage({act}){const [settings,setSettings]=useState({}),[tokens,setTokens]=useState({});useEffect(()=>{api('/settings').then(setSettings)},[]);return <><Title eyebrow="PRIVATE BY DESIGN" title="Настройки" description="Ключи остаются на сервере и не возвращаются в интерфейс."/><section className="panel settings-panel"><h2>Подключения</h2>{[['yougpu','YouGPU API key · только баланс',settings.yougpu_connected],['huggingface','Hugging Face read token',settings.hf_connected],['civitai','Civitai token',settings.civitai_connected]].map(([key,label,ready])=><Field key={key} label={label+' · '+(ready?'подключено':'не задан')}><input type="password" autoComplete="off" value={tokens[key]||''} onChange={e=>setTokens({...tokens,[key]:e.target.value})} placeholder="Вставьте новый ключ для замены"/></Field>)}<Button onClick={()=>act(async()=>{await api('/settings/secrets','PUT',Object.fromEntries(Object.entries(tokens).filter(([,v])=>v)));setTokens({});setSettings(await api('/settings'))},'Ключи сохранены в зашифрованном виде')}>Сохранить подключения</Button><hr/><h3>Развёртывание</h3><p>Адрес: <code>{settings.public_url}</code></p><p>GPU-образ: <code className="break">{settings.agent_image||'AGENT_IMAGE ещё не задан'}</code></p><p className="hint">База, S3 и образ агента задаются через переменные окружения Timeweb. Полная инструкция включена в репозиторий.</p></section></>}
const faq=[['Как начать?','Добавьте HF token и проверьте профиль модели. Загрузите датасет с captions. Создайте инстанс вручную в YouGPU, подключите агента через раздел «Мощности», выберите его для обучения или генерации.'],['Что требуется для Krea 2?','RAW используется для обучения, Turbo — для генерации. Нужны Qwen-Image VAE и Qwen3-VL-4B. Примите условия доступа на Hugging Face. Проверка профиля закрепит ревизии файлов.'],['Как обучить Klein 9B?','Используйте Base9B, FLUX.2 AE и все shards Qwen3 8B. Базовый генератор работает с 50 шагами и guidance 4. Distilled-перенос LoRA в этой сборке отдельно не включён.'],['Как обучается Wan?','Это отдельная видео-LoRA. I2V и T2V используют разные рецепты; A14B имеет high/low эксперты. Фотографии учат внешности, клипы добавляют временные признаки. Выбирайте low, high либо два последовательных запуска.'],['Нужен ли negative prompt?','Зависит от модели и режима. Krea Turbo работает без CFG, поэтому поле отключено. Для Klein Base и обычного Wan оно доступно.'],['Как продолжить обучение?','Сохраните state ZIP, а не только LoRA. При продолжении должны совпадать рецепт, версия датасета и ключевые настройки. Выберите state в форме обучения.'],['Где фотографии, а где веса?','Галерея содержит только фото и видео. Экспортированные LoRA и состояния находятся в разделе моделей. Промежуточные LoRA появляются как отдельные версии.'],['Почему GPU простаивает?','Загрузка, кэширование и CPU offload могут ограничивать скорость. При достаточной VRAM оставьте block swap равным 0. Переход в CPU не является бесплатным ускорением.'],['Можно ли обучать на двух GPU?','В текущей сборке одна GPU обслуживает задачу. Несколько агентов могут выполнять разные задачи. DDP и разделение модели по памяти не включены до реальной GPU-проверки.'],['Как завершить расходы?','Отмена задания и завершение аренды — разные действия. STOPPED у YouGPU продолжает тарифицироваться. Используйте завершение аренды после подтверждённого сохранения файлов.'],['Как формируется стоимость?','Цена за час берётся из каталога провайдера. ETA и стоимость задачи требуют замеров для конкретного рецепта, оборудования и настроек. Без замера приложение прямо сообщает об этом.'],['Как готовить видео?','Разделяйте видео на короткие сцены; перекрытие клипов допустимо. Клипы одного источника сохраняют общую группу и не расходятся между train и validation. Сначала проверьте лица, анатомию и captions.'],['Что значат 403, 404 и OOM?','403 — проверьте доступ и токен. 404 — имя или ревизию компонента. OOM — уменьшите нагрузку либо выберите GPU с большей памятью. Ошибки загрузки не лечатся повторным запуском обучения.']];
function Help(){return <><Title eyebrow="A LITTLE GUIDANCE" title="Помощь" description="Короткие ответы рядом с вашей работой."/><div className="faq">{faq.map(([q,a],n)=><details className="panel" key={q} open={n===0}><summary>{q}<ChevronDown size={17}/></summary><p>{a}</p></details>)}</div><div className="panel"><h3>Статус этой сборки</h3><p>Сервер и команды проверяются CPU-тестами. GPU-рецепты требуют реального прогона на выбранной мощности. Приложение не объявляет эти проверки выполненными автоматически.</p><a href="https://github.com/kohya-ss/musubi-tuner" target="_blank" rel="noreferrer">Документация тренера ↗</a></div></>}
createRoot(document.getElementById('root')).render(<App/>);

function EditCharacter({character:c,data,act,onDone}){const [v,set]=useState({name:c.name,description:c.description,face_id:c.face_id||'',body_id:c.body_id||''});return <form onSubmit={e=>{e.preventDefault();act(async()=>{await api('/characters/'+c.id,'PATCH',v);onDone()},'Эталоны сохранены')}}><Field label="Имя"><input value={v.name} onChange={e=>set({...v,name:e.target.value})}/></Field><Field label="Особенности внешности"><textarea value={v.description} onChange={e=>set({...v,description:e.target.value})}/></Field><p>FACE_ANCHOR</p><Reference data={data} act={act} value={v.face_id} onChange={x=>set({...v,face_id:x})}/><p>BODY_ANCHOR</p><Reference data={data} act={act} value={v.body_id} onChange={x=>set({...v,body_id:x})}/><p className="hint">Эталоны используются для визуальной проверки. Добавление эталона само по себе не обучает LoRA.</p><Button>Сохранить</Button></form>}
function VideoSettings({dataset,act,onDone}){const [v,set]=useState({clip_seconds:3,overlap:.5,fps:16,frames_only:false,scene_cut:true});return <form onSubmit={e=>{e.preventDefault();act(async()=>{await api('/jobs','POST',{recipe:'dataset.video',character_id:dataset.character_id,params:{...v,dataset_id:dataset.id}});onDone()},'Подготовка видео добавлена в очередь')}}>{[['clip_seconds','Длительность клипа, сек'],['overlap','Перекрытие, сек'],['fps','FPS']].map(([k,label])=><NumberField key={k} label={label} step={k==='fps'?1:.25} value={v[k]} onChange={x=>set({...v,[k]:x})}/>)}<label className="check"><input type="checkbox" checked={v.scene_cut} onChange={e=>set({...v,scene_cut:e.target.checked})}/>Учитывать смены сцен</label><label className="check"><input type="checkbox" checked={v.frames_only} onChange={e=>set({...v,frames_only:e.target.checked})}/>Извлечь отдельные кадры вместо клипов</label><Button>Подготовить</Button></form>}

function ProfilePicker({recipe,data,value,onChange}){return <Field label="Профиль компонентов"><select value={value||recipe?.family||''} onChange={e=>onChange(e.target.value)}>{data.profiles.filter(p=>p.family===recipe?.family).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field>}

function DatasetSettings({dataset,act,onDone}){
 const [value,setValue]=useState(null);
 useEffect(()=>{api('/datasets/'+dataset.id+'/settings').then(setValue)},[dataset.id]);
 if(!value)return <p>Загрузка настроек…</p>;
 const change=(k,v)=>setValue(x=>({...x,[k]:v}));
 return <form onSubmit={e=>{e.preventDefault();act(async()=>{await api('/datasets/'+dataset.id+'/settings','PUT',value);onDone()},'Настройки сохранены')}}>
 <p>Персонаж: {dataset.character_id} · trigger: {value.trigger}. Trigger изменяется через персонажа.</p>
 <Field label="Тип материала"><select value={value.material} onChange={e=>change('material',e.target.value)}>{['image','video','mixed'].map(x=><option key={x}>{x}</option>)}</select></Field>
 <Field label="Правила captions"><textarea value={value.caption_rules} onChange={e=>change('caption_rules',e.target.value)}/></Field>
 <NumberField label="Разрешение по умолчанию" value={value.resolution} onChange={v=>change('resolution',v)}/>
 <NumberField label="Доля validation" min={0} max={.5} step={.05} value={value.validation_ratio} onChange={v=>change('validation_ratio',v)}/>
 <Field label="Стратегия отбора"><select value={value.selection} onChange={e=>change('selection',e.target.value)}><option value="manual">Ручная проверка</option><option value="exclude_duplicates">Исключать кандидаты дубликатов</option></select></Field>
 <p className="hint">Разрешение и правила — настройки набора; параметры обучения задаются отдельно. Близкие дубликаты всегда требуют ручной проверки.</p><Button>Сохранить</Button></form>
}
